    function runtimeEffectKey(card){const ids=new Set(card.effects.map(effect=>effect.effectId)),multiFx=card.effects.find(effect=>effect.effectId==='summon_barrage'||effect.effectId==='sweep_attack');if(multiFx)return (multiFx.effectId==='summon_barrage'?'barrage-':'sweep-')+(multiFx.amount||(multiFx.effectId==='summon_barrage'?2:50));const triggers=new Set(card.effects.map(effect=>effect.trigger)),towerEffects=['freeze_strongest','frost_nova','turn_invulnerable','weaken_all','shock_storage','explosive_mark','blink_shield','armor_pierce','arcane_arrow','mass_heal','heal_bless','piercing_shot','battle_enhance','summon_wolf','sword_aura','necromancy','board_damage','draw','cleanse','bounce','mana_ramp','resurrect','negate_summon','self_replicate','black_flame','swarm_fury','swarm_bulwark','global_destroy','lightning_strike','chain_lightning'];for(const effect of towerEffects)if(ids.has(effect))return effect.replaceAll('_','-');if(ids.has('lone_wolf'))return 'lone-wolf';if(ids.has('comeback'))return 'comeback-flare';if(ids.has('buff')&&triggers.has('on_field_disadvantage'))return 'last-stand';if(ids.has('burn'))return 'burn';if(ids.has('heal'))return 'heal-lowest';if(ids.has('prevent_damage')&&triggers.has('on_hero_attacked'))return 'counter-current';if(card.cardType==='trap'&&triggers.has('on_enemy_summon'))return 'ambush-mine';if(ids.has('attack_down'))return 'champion-control';if(ids.has('damage')&&card.effects.some(effect=>effect.target==='enemy_hero'))return 'hero-bolt';if(ids.has('buff'))return 'fire-infusion';if(card.cardType==='champion'&&!card.effects.length)return ({fire:'flame-awakening',water:'tide-grace',wind:'rush',earth:'stone-aegis',neutral:'fate-draw'})[card.auraKey]||'fate-draw';return '';}
