    const FX_PRIORITY={choice:200,ultimate:100,guardian:90,desperate:80,magic:60,trap:60,cinematic:40,banner:20};/* choice: 유저 입력을 기다리는 오버레이. hold:0 으로 올려 결정 전까지 필드를 멈춘다. 어떤 연출에도 선점당하면 안 된다. */
