    function animateCrackerTransfer(amount,direction,onDone){const wallet=document.querySelector('#cracker-count'),enemy=document.querySelector('.duel-hud .enemy .avatar'),reward=direction==='reward',source=reward?enemy:wallet,target=reward?wallet:enemy;if(!source||!target||amount<=0){onDone();return;}const a=source.getBoundingClientRect(),b=target.getBoundingClientRect(),startX=a.left+a.width/2,startY=a.top+a.height/2,endX=b.left+b.width/2,endY=b.top+b.height/2,dx=endX-startX,dy=endY-startY,count=reward?24:14;source.animate([{filter:'brightness(1)',transform:'scale(1)'},{filter:'brightness(2.8)',transform:'scale(1.18)'},{filter:'brightness(1)',transform:'scale(1)'}],{duration:520,easing:'ease-out'});for(let i=0;i<count;i++){const chip=document.createElement('i'),spread=(i-(count-1)/2)*3.2,arc=(reward?-110:-75)-Math.abs(spread)*.18,duration=950+(i%6)*70,delay=i*38;chip.className='cracker-transfer';chip.textContent=i%4===0?'✦':'◆';chip.style.left=startX+'px';chip.style.top=startY+'px';chip.style.fontSize=(reward?18+(i%4)*3:16+(i%3)*2)+'px';chip.style.animation='none';document.body.appendChild(chip);const flight=chip.animate([{transform:'translate(-50%,-50%) scale(.2) rotate(0)',opacity:0,offset:0},{transform:'translate(calc('+dx*.38+'px - 50%),calc('+(dy*.38+arc+spread)+'px - 50%)) scale(1.45) rotate(120deg)',opacity:1,offset:.38},{transform:'translate(calc('+dx*.72+'px - 50%),calc('+(dy*.72+arc*.55-spread*.3)+'px - 50%)) scale(1) rotate(250deg)',opacity:1,offset:.72},{transform:'translate(calc('+(dx+(i%5-2)*5)+'px - 50%),calc('+(dy+(i%3-1)*4)+'px - 50%)) scale(.35) rotate(420deg)',opacity:0,offset:1}],{duration,delay,easing:'cubic-bezier(.18,.7,.2,1)',fill:'forwards'});flight.onfinish=()=>chip.remove();}const caption=document.createElement('div');caption.className='cracker-transfer-caption';caption.textContent=reward?'◆ 승리 보상 · 크래커 '+amount+' 강탈':'기권 · 크래커 '+amount+' 전달';document.body.appendChild(caption);setTimeout(()=>{target.animate([{filter:'brightness(1)',transform:'scale(1)'},{filter:'brightness(3)',transform:'scale(1.32)'},{filter:'brightness(1)',transform:'scale(1)'}],{duration:650,easing:'cubic-bezier(.2,.8,.2,1)'});},1150);setTimeout(()=>caption.remove(),1750);setTimeout(onDone,1700);}
    function surrenderBattle(button){if(document.querySelector('#result').classList.contains('show')||surrenderPending)return;if(!button.classList.contains('confirm')){button.classList.add('confirm');button.textContent='확인?';button.title='다시 누르면 기권하고 패배 처리됩니다.';clearTimeout(surrenderConfirmTimer);surrenderConfirmTimer=setTimeout(()=>{button.classList.remove('confirm');button.textContent='기권';button.title='전투 기권';},2600);return;}clearTimeout(surrenderConfirmTimer);surrenderPending=true;resultPending=true;button.disabled=true;button.textContent='기권 처리';try{settleRank(false);}catch(error){console.error('기권 랭크 정산 실패',error);}settleBattleUi();try{sfx('lose');}catch(error){console.error('기권 효과음 재생 실패',error);}showBattleResult(false,'기권했습니다. 기권은 패배로 계산됩니다.');}
    function restartBattleToAuraSelect(){const next=new URL(location.href);/* QA용 자동 선택 옵션이 남아 있으면 새 판에서도 난이도·오라 선택을 건너뛰므로 제거한다. */next.searchParams.delete('difficulty');next.searchParams.delete('guardian');next.searchParams.delete('skipIntro');location.replace(next.href);}
    function showBattleResult(win,reason){const rank=lastRankResult||{before:rankState.score,after:rankState.score,delta:0,ranked:false,tier:tierFor(rankState.score)},beforeTier=tierFor(rank.before),afterTier=tierFor(rank.after),deltaLabel=rank.ranked?(rank.delta>0?'+'+rank.delta:String(rank.delta)):'변동 없음';document.querySelector('#result-title').textContent=win?'승리':'패배';document.querySelector('#result-copy').textContent=reason;document.querySelector('#result-rank').innerHTML='<div class="rank-before"><span>이전 티어</span><br><strong>'+beforeTier.name+' · '+rank.before+'</strong></div><div class="rank-delta">'+deltaLabel+'</div><div class="rank-after"><span>현재 티어</span><br><strong>'+afterTier.name+' · '+rank.after+'</strong></div>';document.querySelector('#result-rank-note').textContent=rank.ranked?'배치 '+rankState.placementPlayed+' / 5 · 시즌 전적 '+rankState.wins+'승 '+rankState.losses+'패':MATCH_TYPE==='bot'?'봇 대전은 티어 점수가 변하지 않습니다.':'티어 점수 변동 없음';const resultNode=document.querySelector('#result');resultNode.classList.toggle('lose',!win);resultNode.classList.remove('restart-transition','auto-transition','narrative-title');resultNode.classList.add('show');}
    function settleBattleUi(){setBattlePhase('ended');fxClear();document.querySelectorAll('.card,.unit').forEach(node=>node.classList.remove('selected','attacking','field-attacker','field-target'));document.querySelectorAll('.initiative-banner,.effect-narration,.aura-awaken-choice').forEach(node=>node.remove());const guide=document.querySelector('#hand-guide');if(guide){guide.classList.remove('initiative-guide');guide.textContent='전투 종료';}const end=document.querySelector('#end-turn');if(end){end.disabled=true;end.textContent='전투 종료';end.style.opacity='.55';}const surrender=document.querySelector('#surrender-action');if(surrender)surrender.disabled=true;}
    function finish(win,reason,forfeit){if(resultPending||document.querySelector('#result').classList.contains('show'))return;resultPending=true;settleRank(win);settleBattleUi();sfx(win?'win':'lose');if(win&&!victoryRewardGranted){victoryRewardGranted=true;collectionState.crackers=(collectionState.crackers||0)+PVC_CLEAR_CRACKER_REWARD;const cookieReward=grantCookieFragments(VICTORY_COOKIE_REWARD,'game_win');persistCollection();updateCrackerHud();showBattleResult(true,reason+' PvC 클리어 보상으로 크래커 '+PVC_CLEAR_CRACKER_REWARD+'개와 쿠키조각 '+cookieReward+'개를 얻었습니다.');return;}showBattleResult(win,reason,Boolean(forfeit));}
    /* 토큰 일러스트: 새 토큰을 추가하면 여기에 이미지도 함께 등록한다 (비어 있으면 ✦ 빈 칸으로 보임) */
    const TOKEN_ART={'necromancy-token':'assets/tokens/necro-spirit.webp','wolf-token':'assets/tokens/mana-wolf.webp','self-replicate':'assets/characters/generated/mitosis-slime.png'};
    function summonBattleToken(name,attack,hp,element,effect=''){const lane=document.querySelector('.summon-zone');if(!lane||lane.querySelectorAll('.unit').length>=FIELD_CARD_LIMIT)return null;const unit=document.createElement('div');unit.className='unit '+element;unit.dataset.effect=effect;unit.dataset.maxHp=String(hp);const art=TOKEN_ART[effect]||'';unit.dataset.art=art;unit.onclick=()=>selectUnit(unit);unit.innerHTML='<div class="emoji">'+(art?'<img class="creature-art" src="'+art+'" alt="'+name+'">':'✦')+'</div><h4>'+name+'</h4><div class="stats"><span>⚔ '+attack+'</span><span>♥ '+hp+'</span></div>';lane.appendChild(unit);unit.classList.add('exhausted');showSkillEffect('rush',unit,name+' 소환');writeLog('<strong>'+name+'</strong>이 전장에 소환되었습니다.');return unit;}
    function resolveSelfReplication(){if(!selfReplicationPrimed)return;selfReplicationPrimed=false;const source=document.querySelector('.summon-zone .unit[data-effect="self-replicate"]'),lane=document.querySelector('.summon-zone');if(!source||!lane||lane.querySelectorAll('.unit').length>=FIELD_CARD_LIMIT)return;const copy=summonBattleToken('미토시스 슬라임 분체',1,1,'water','self-replicate');if(!copy)return;const art=source.dataset.art||'assets/characters/generated/mitosis-slime.png';copy.dataset.art=art;copy.dataset.replica='true';copy.querySelector('.emoji').innerHTML='<img class="creature-art" src="'+art+'" alt="미토시스 슬라임 분체">';showSkillEffect('heal',copy,'미토시스 · 분체 +1');writeLog('<strong>자가 증식:</strong> 마나 2를 남긴 보상으로 미토시스 슬라임 분체 1장이 생성되었습니다.');updateSynergyHud();}
    function triggerBattlecry(unit){const effect=unit.dataset.effect,name=unit.querySelector('h4').textContent,allies=[...document.querySelectorAll('.summon-zone .unit')],enemies=[...document.querySelectorAll('.arena .lane:first-child > .unit')];const barrage=/^barrage-(\d+)$/.exec(effect||'');if(barrage&&enemies.length){const barrageDamage=Number(barrage[1]),barrageElement=getElement(unit);enemies.forEach((target,i)=>setTimeout(()=>{if(!target.isConnected)return;showUnitSpellFx(target,barrageElement);setTimeout(()=>{if(!target.isConnected)return;const result=damageUnit(target,barrageDamage,barrageElement);if(!result.blocked&&result.hp<=0)setTimeout(()=>target.remove(),650);},combatMs(220));},i*combatMs(120)));writeLog('<strong>'+name+'</strong>이(가) 소환되며 적 챔프 '+enemies.length+'장 전체에게 '+barrageDamage+' 피해를 줬습니다.');}if(effect==='rush'||effect==='blink-shield'){unit.dataset.rush='true';unit.classList.remove('exhausted');if(effect==='blink-shield'){unit.dataset.shield='true';unit.style.boxShadow='0 0 0 3px #8bdcff,0 0 24px #62bdff';showSkillEffect('shield',unit,'디멘션 이지스 · 보호막');}else{if(getElement(unit)==='wind')setTimeout(()=>showCinematicSkillEffect('gust',name+' · 게일 러시',cinematicVariantFor(name)),180);setTimeout(()=>showSkillEffect('rush',unit,'게일 러시 · 즉시 행동'),520);}}if(effect==='flame-awakening'){const atk=unit.querySelector('.stats span:first-child');atk.textContent='⚔ '+(Number(atk.textContent.replace(/[^0-9]/g,''))+1);showSkillEffect('burn',unit,'블레이즈 하트 · 공격 +1');}if(effect==='tide-grace'){const healed=Math.min(2,HERO_MAX_HP-playerHp);if(healed>0){playerHp+=healed;updateHeroHealth();showSkillEffect('heal',unit,'아쿠아 그레이스 · 영웅 +'+healed);}}if(effect==='stone-aegis'){unit.dataset.shield='true';unit.style.boxShadow='0 0 0 3px #d6a86a,0 0 24px #c99c58';showSkillEffect('shield',unit,'테라 이지스 · 보호막');}if(effect==='fate-draw'&&deck.length&&document.querySelectorAll('.hand .card').length<8){setTimeout(drawCard,0);showSkillEffect('rush',unit,'페이트 콜 · 드로우 1');}if(effect==='freeze-strongest'&&enemies.length){const target=enemies.sort((a,b)=>Number(b.querySelector('.stats span:first-child').textContent.replace(/[^0-9]/g,''))-Number(a.querySelector('.stats span:first-child').textContent.replace(/[^0-9]/g,'')))[0],atk=target.querySelector('.stats span:first-child');atk.textContent='⚔ '+Math.max(0,Number(atk.textContent.replace(/[^0-9]/g,''))-2);target.classList.add('exhausted');freezeUnit(target);frostFx([target]);showSkillEffect('shield',target,'프로스트 록 · 공격 −2');}if(effect==='weaken-all')enemies.forEach((target,i)=>setTimeout(()=>{const atk=target.querySelector('.stats span:first-child');atk.textContent='⚔ '+Math.max(0,Number(atk.textContent.replace(/[^0-9]/g,''))-1);showSkillEffect('shield',target,'쇠약 −1');},i*90));if(effect==='arcane-arrow'){enemyHp=Math.max(0,enemyHp-2);updateHeroHealth();impact(document.querySelector('.enemy .avatar'),2,'wind');if(enemyHp<=0)finish(true,'소환 효과로 상대 영웅을 쓰러뜨렸습니다.');}if(effect==='mass-heal')allies.forEach(target=>{const hp=target.querySelector('.stats span:last-child'),old=Number(hp.textContent.replace(/[^0-9]/g,'')),healed=Math.min(2,Math.max(0,Number(target.dataset.maxHp)-old));if(healed){hp.textContent='♥ '+(old+healed);showSkillEffect('heal',target,'광역 치유 +'+healed);}});if(effect==='heal-bless'){const target=allies.sort((a,b)=>Number(a.querySelector('.stats span:last-child').textContent.replace(/[^0-9]/g,''))-Number(b.querySelector('.stats span:last-child').textContent.replace(/[^0-9]/g,'')))[0];if(target){const hp=target.querySelector('.stats span:last-child'),old=Number(hp.textContent.replace(/[^0-9]/g,'')),healed=Math.min(3,Math.max(0,Number(target.dataset.maxHp)-old));hp.textContent='♥ '+(old+healed);target.dataset.shield='true';showSkillEffect('shield',target,'힐링 블레스 · +'+healed);}}if(effect==='battle-enhance')allies.forEach(target=>{const atk=target.querySelector('.stats span:first-child');atk.textContent='⚔ '+(Number(atk.textContent.replace(/[^0-9]/g,''))+1);showSkillEffect('rush',target,'전투 강화 +1');});if(effect==='summon-wolf')summonBattleToken('마력 늑대',2,2,'earth','wolf-token');if(effect==='sword-aura'&&enemies[0]){const result=damageUnit(enemies[0],3,'wind');showSkillEffect('rush',enemies[0],'소드 오라 · 3');if(result.hp<=0)setTimeout(()=>enemies[0].remove(),650);}if(effect==='lone-wolf')updateLoneWolfBonuses();updateSynergyHud();}
    function triggerDeathrattle(unit){ if(unit.dataset.deathEffect==='none')return; }
    const triggerBattlecryCore=triggerBattlecry;
    triggerBattlecry=function(unit){triggerBattlecryCore(unit);const effect=unit.dataset.effect;if(effect==='draw'){for(let i=0;i<2;i++)setTimeout(()=>{if(deck.length&&document.querySelectorAll('.hand .card').length<8)drawCard();},i*220);/* 덱·손패 확인은 실제로 뽑는 순간에 */showSkillEffect('rush',unit,'전술 통찰 · 드로우 2');}if(effect==='board-damage'){const targets=[...document.querySelectorAll('.arena .unit')].filter(target=>target!==unit);targets.forEach((target,i)=>setTimeout(()=>{if(!target.isConnected)return;const result=damageUnit(target,4,'fire');if(result.hp<=0)setTimeout(()=>target.remove(),650);},i*90));showSkillEffect('burn',unit,'재앙 강림 · 전체 4');}};
    function showSummonAttack(unit,enemyName,damage,onImpact){if(damage===0)sfx('shield');const hero=document.querySelector('.player .avatar');if(hero)fieldAttack(unit,hero,{label:damage+' 피해',onImpact});else onImpact?.();}
    /* 상대 AI: 마나는 플레이어와 같은 규칙(과한 선점 없음). 손패에서 마나를 가장 알차게 쓰는 조합을 골라 한 턴에 여러 장 소환하고,
       오라 공명/조화를 노리며, 공격력 대비 체력이 높은 유닛을 앞세워 주력을 보호한다. ENEMY_AI.manaMirrorsPlayer=false 면 예전 마나 방식. */
    const ENEMY_AI={manaMirrorsPlayer:true,atkWeight:1,hpWeight:.7,manaWeight:.35,synergyWeight:1.5};
    function enemyUnitValue(card){return (card.atkFinal??card.atk)*ENEMY_AI.atkWeight+card.hp*ENEMY_AI.hpWeight;}
    function enemyFieldSynergy(elements){const real=elements.filter(e=>e&&e!=='neutral'),unique=new Set(real).size;let bonus=0;elements.forEach(e=>{if(e&&e!=='neutral'&&real.filter(x=>x===e).length>=2)bonus++;if(unique>=3)bonus++;});return bonus;}
    function planEnemyPlays(hand,mana,slots,fieldElements){const candidates=[],n=Math.min(hand.length,12),difficulty=enemyDifficultyConfig(),playerUnits=[...document.querySelectorAll('.summon-zone .unit:not([data-destroyed="true"])')],underPressure=playerUnits.length>document.querySelectorAll('.arena .lane:first-child > .unit:not([data-destroyed="true"])').length;for(let mask=1;mask<(1<<n);mask++){let cost=0,count=0,value=0,attack=0,health=0,valid=true;const elements=[...fieldElements];for(let i=0;i<n;i++)if(mask&(1<<i)){if(hand[i].spell){valid=false;break;}cost+=hand[i].cost;count++;value+=enemyUnitValue(hand[i]);attack+=hand[i].atkFinal??hand[i].atk;health+=hand[i].hp;elements.push(hand[i].el);}if(!valid||cost>mana||count>slots)continue;let score=value+cost*ENEMY_AI.manaWeight+enemyFieldSynergy(elements)*ENEMY_AI.synergyWeight;if(difficulty.searchDepth>=1)score+=enemyFieldSynergy(elements)*.8+(underPressure?health*.18:attack*.15);if(difficulty.searchDepth>=2){const exposedDamage=Math.max(0,playerUnits.reduce((sum,u)=>sum+(Number(u.querySelector('.stats span:first-child').textContent.replace(/[^0-9]/g,''))||0),0)-health);score-=exposedDamage*.22;score+=Math.min(mana,cost)*.15;}candidates.push({score,mask});}if(!candidates.length)return[];candidates.sort((a,b)=>b.score-a.score);let choice=candidates[0];if(difficulty.mistakeRate&&candidates.length>1&&engineAdapter.random()<difficulty.mistakeRate){const pool=candidates.slice(1,Math.min(candidates.length,difficulty.searchDepth?3:5));choice=pool[Math.floor(engineAdapter.random()*pool.length)]||choice;}return hand.slice(0,n).map((_,i)=>i).filter(i=>choice.mask&(1<<i));}
    function showUltimateAggroIntercept(target){if(!target?.isConnected||target.dataset.destroyed==='true')return;showSkillEffect('shield',target,'전역 도발 · 공격 강제');writeLog('<strong>'+target.querySelector('h4').textContent+'</strong>의 전역 도발이 공격 대상을 자신으로 강제했습니다.');}
    function chooseEnemyAttackTarget(unit,targets){const ultimateAggro=targets.find(u=>u.dataset.ultimateAggro==='true');if(ultimateAggro){showUltimateAggroIntercept(ultimateAggro);return ultimateAggro;}const taunt=targets.find(u=>u.dataset.taunt==='true');if(taunt)return taunt;if(!targets.length)return null;if(enemyDifficulty==='normal')return targets[Math.floor(engineAdapter.random()*targets.length)];if(enemyDifficulty==='nightmare')return targets[0];const attack=Number(unit.querySelector('.stats span:first-child').textContent.replace(/[^0-9]/g,''))||0,stat=u=>{const nodes=u.querySelectorAll('.stats span'),atk=Number(nodes[0]?.textContent.replace(/[^0-9]/g,''))||0,hp=Number(nodes[1]?.textContent.replace(/[^0-9]/g,''))||0;return {u,atk,hp,kill:hp<=attack};},ranked=targets.map(stat).sort((a,b)=>(Number(b.kill)-Number(a.kill))||(b.kill?b.atk-a.atk:a.hp-b.hp));return ranked[0].u;}
    function arrangeEnemyLane(lane){const carry=unit=>{const [atk,hp]=[...unit.querySelectorAll('.stats span')].map(node=>Number(node.textContent.replace(/[^0-9]/g,''))||0);return atk-hp*.5;};[...lane.querySelectorAll(':scope > .unit')].sort((a,b)=>carry(a)-carry(b)).forEach(unit=>lane.appendChild(unit));}
    const unitStat=(unit,index)=>Number(unit?.querySelectorAll('.stats span')[index]?.textContent.replace(/[^0-9]/g,''))||0;
    function enemyDraw(count=1){for(let i=0;i<count&&enemyDeck.length&&enemyHand.length<8;i++)enemyHand.push(gradeCardData(enemyDeck.shift(),'enemy'));}
    function summonEnemyPriorityChampion(lane){if(lane.querySelector(':scope > .unit:not([data-destroyed="true"])'))return false;const picks=planEnemyPlays(enemyHand,enemyMana,1,[]);if(!picks.length)return false;const index=picks[0],data=enemyHand.splice(index,1)[0];enemyMana-=data.cost;enemySummonUnit(lane,data);writeLog('<strong>상대 전개 우선:</strong> 빈 필드를 막기 위해 마법·궁극기보다 챔피언을 먼저 소환했습니다.');return true;}
    function enemyDamageUnits(units,damage,element='neutral',burnSource=''){/* 상대 효과도 대상을 먼저 보여준다 — 아무 표시 없이 카드가 사라지면 누가 왜 죽었는지 알 수 없다 (2026-11-07). */markSpellTargets(units.filter(unit=>unit?.isConnected),'상대 효과 · '+Math.max(0,damage)+' 피해','#ff8f8f');units.forEach(unit=>{if(!unit?.isConnected)return;const result=damageUnit(unit,Math.max(0,damage),element);if(burnSource&&element==='fire'&&!result.blocked&&result.hp>0)applyBurn(unit,1,burnSource);if(!result.blocked&&result.hp<=0){unit.dataset.destroyed='true';setTimeout(()=>unit.remove(),650);}});}
    function enemySpellScore(card){const foes=document.querySelectorAll('.summon-zone .unit:not([data-destroyed="true"])').length,allies=document.querySelectorAll('.arena .lane:first-child > .unit:not([data-destroyed="true"])').length,effect=card.effect||'';let score=card.cost*.2;if(card.trap)score+=effect.includes('counter-current')?4:foes?3:1;if(/damage|black-flame|frost-nova|giant-hunt|judgment|weight-toll|global-destroy/.test(effect))score+=foes*2;if(/heal|bulwark|cleanse|life-siphon/.test(effect))score+=(HERO_MAX_HP-enemyHp)/12+allies;if(/draw|insight/.test(effect))score+=Math.max(0,6-enemyHand.length);if(effect==='mana-ramp')score+=turnNumber<7?5:1;if(effect==='resurrect')score+=enemyGraveyard.length*3;if(effect==='bounce')score+=foes*2;return score;}
    function setEnemyMagic(){const free=Math.max(0,2-enemySetMagic.length),choices=enemyHand.map((card,index)=>({card,index})).filter(x=>x.card.spell&&x.card.cost<=enemyMana).sort((a,b)=>enemySpellScore(b.card)-enemySpellScore(a.card)).slice(0,free).sort((a,b)=>b.index-a.index);choices.forEach(({card,index})=>{enemyHand.splice(index,1);enemyMana-=card.cost;enemySetMagic.push({...card,readyTurn:turnNumber+Math.max(1,card.delay||1)});writeLog(card.trap?'<strong>상대</strong>가 함정 카드를 뒤집어 세트했습니다.':'<strong>상대</strong>가 마법 <strong>'+card.name+'</strong>을(를) 세트했습니다.');});}
