    function attack(target,automatic=false){ if(battlePhase!=='setup'&&!automatic)return;const selected=document.querySelector('.unit.selected'); if(!selected){ writeLog('먼저 내 소환수 카드를 선택하세요.'); return; } if(selected.closest('.lane')===target.closest('.lane')){ selectUnit(target,automatic); return; }const enemyLane=document.querySelector('.arena .lane:first-child'),priority=enemyLane.querySelector(':scope > .unit[data-ultimate-aggro="true"]:not([data-destroyed="true"])')||enemyLane.querySelector(':scope > .unit:not([data-destroyed="true"])');if(!priority){attackFace(document.querySelector('.duel-hud .enemy'),automatic);return;}const sweep=/^sweep-(\d+)$/.exec(selected.dataset.effect||'');if(sweep){const ratio=Number(sweep[1])/100,sweepTargets=[...document.querySelectorAll('.arena .lane:first-child > .unit:not([data-destroyed="true"])')];sweepTargets.forEach((enemy,i)=>setTimeout(()=>{if(!selected.isConnected||!enemy.isConnected||enemy.dataset.destroyed==='true')return;resolveDuel(selected,enemy,{playerAttack:i===0,ratio});},i*combatMs(260)));writeLog('<strong>'+selected.querySelector('h4').textContent+'</strong>의 기본 공격이 적 챔프 '+sweepTargets.length+'장 전체를 휩쓸었습니다. (공격력의 '+sweep[1]+'%)');}else{if(priority.dataset.ultimateAggro==='true')showUltimateAggroIntercept(priority);else if(target!==priority&&!automatic)writeLog('공격 대상은 상대 전장의 가장 왼쪽 카드로 자동 지정됩니다.');resolveDuel(selected,priority,{playerAttack:true});}selected.classList.remove('selected','attacking');if(selected.isConnected)selected.classList.add('exhausted');selected.dataset.attacked='1';document.querySelector('#hand-guide').textContent=automatic?'내 챔프 전투 처리 중':'내 카드 순서는 준비 턴에 드래그해 변경할 수 있습니다'; }
